  desiredProductIDs.includes(item.ProductID) && item.IsEnabled && item.available
);

const elements = filteredItems.map(item => ({
  title: item.Name,
  image_url: (item.imagelink && item.imagelink !== "placeholder")
    ? item.imagelink
    : `https://via.placeholder.com/300x200?text=${encodeURIComponent(item.Name)}`,
  subtitle: item.description || "No description available",
  buttons: [
    {
      type: "postback",
      title: "Add to Cart",
      payload: `ADD_${item.ProductID}`
    }
  ]
}));

elements.push({
  title: "Main Menu",
  image_url: "https://via.placeholder.com/300x200?text=Main+Menu",
  subtitle: "Return to main menu",
  buttons: [
    {
      type: "postback",
      title: "Go Back",
      payload: "REVIEW_MENU"
    }
  ]
});

const responsePayload = {
  messaging_type: "RESPONSE",
  recipient: { id: senderId },
  message: {
    attachment: {
      type: "template",
      payload: {
        template_type: "generic",
        elements: elements
      }
    }
  }
};

return [{ json: responsePayload }];

